fn main(){if floatboard_core::build_identity::handle(){return;}let args:Vec<String>=std::env::args().collect();let result=args.iter().position(|a|a=="--request").and_then(|i|args.get(i+1)).ok_or_else(||"缺少更新请求".to_string()).and_then(|p|floatboard_core::update_install::apply_request(std::path::Path::new(p)));if let Err(error)=result{if let Some(path)=args.iter().position(|a|a=="--request").and_then(|i|args.get(i+1)){let _=floatboard_core::store::atomic_json(&std::path::Path::new(path).with_extension("error"),&serde_json::json!({"error":error}));}eprintln!("{error}");std::process::exit(1);}}
